bodies.css_snippet:
/* reconstructed from measured tokens */
body { font-family: "Georgia", Arial, sans-serif; color: #083852; background: #FFFFFF; }
h1, h2, h3 { font-family: "Georgia", Arial, sans-serif; }
a { color: #CDAC8B; }
.site-header, .main-menu { background: #CDAC8B; color: #FFFFFF; }
.footer { background: #CDAC8B; color: #FFFFFF; }

body {
  font-family: 'Roboto', Arial, sans-serif;
  color: #1A1A1A;
  background-color: #FFFFFF;
}
.main-nav {
  background-color: #FFFFFF;
  border-bottom: 1px solid #E0E0E0;
}
.main-nav a {
  color: #1A1A1A;
  font-weight: 500;
  padding: 14px 18px;
}
.featured-ticker {
  background-color: #CE1126;
  color: #FFFFFF;
  font-size: 13px;
}
.news-card {
  background-color: #F5F5F5;
  border-radius: 4px;
  overflow: hidden;
}
.news-card .date {
  color: #1B3D6D;
  font-size: 12px;
  font-weight: 700;
}
.newsletter-cta {
  background-color: #1B3D6D;
  color: #FFFFFF;
  padding: 32px;
}

body {
  font-family: Arial, Helvetica, sans-serif;
  color: #1D1D1B;
  background-color: #FFFFFF;
}
.site-header {
  background-color: #FFFFFF;
  border-bottom: 4px solid #00376E;
}
.mega-menu > li > a {
  color: #00376E;
  font-weight: 700;
  text-transform: uppercase;
  font-size: 13px;
}
.emergency-bar {
  background-color: #FFB81C;
  color: #1D1D1B;
  font-weight: 700;
  padding: 6px 12px;
}
.wanted-grid img {
  width: 100px;
  height: 130px;
  object-fit: cover;
  border: 1px solid #EEF2F6;
}
.news-card .kicker {
  color: #00376E;
  font-size: 11px;
  text-transform: uppercase;
}
